  <section class="reg"><div class="reg-h"><h2 class="t-heading">${ic('info')}Details</h2></div><div class="reg-b"><dl class="kvs">${[['Link name', `[[scene/${esc(x.link)}]]`], ['Tied to', x.period ? `<a href="${calHash(unkey(x.period).y, unkey(x.period).sg, unkey(x.period).d, 'month')}">${esc(dateName(x.period))}</a>` : '<span class="t-meta">No date</span>']].map(([a, b]) => `<div class="kv"><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl><button type="button" class="btn" data-s="scene-period" data-id="${x.id}">Set the date</button></div></section>
