document.addEventListener('change', (e) => { if (e.target.matches && e.target.matches('[data-lv="being"]')) { LV.being = e.target.value; csRefresh(true); } if (e.target.matches && e.target.matches('textarea[data-note]')) { const s = sesOf(); notesOf(s)[e.target.dataset.note] = e.target.value; toast({ title: 'Note saved' }); } });
